INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 5, 'theory', 'Quiz: Overcommit, Ballooning and KSM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 0, 'Why does memory overcommit usually work?', '["Physical memory grows by itself", "Guests rarely use everything they were given: some is taken by caches and pages not read for a long time", "The hypervisor compresses all memory", "Guests exchange pages among themselves"]', 1, 'As long as not all guests demand their share at once, total consumption stays below physical memory. The risk is swapping or the out-of-memory killer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 1, 'Why is hypervisor-level swapping considered a last resort?', '["It is forbidden in KVM", "It encrypts pages", "The hypervisor doesn''t know which pages the guest needs; double swapping is also possible", "It only works for Windows"]', 2, 'The hypervisor may swap out working data, and the guest also uses swap itself, so a page can end up on disk twice.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 2, 'How does ballooning work?', '["A driver in the guest requests pages from the guest kernel, which decides what to sacrifice, and reports the addresses to the hypervisor", "The hypervisor swaps out random pages of the guest", "The balloon lowers the processor frequency", "The balloon compresses the guest''s disk"]', 0, 'The balloon is an ordinary request inside the guest: the guest kernel gives up free pages first, then cache, and only as a last resort pushes data out to swap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 3, 'What does KSM do?', '["Encrypts guest memory", "Compresses pages", "Moves memory to disk", "Finds pages with identical contents and keeps one copy, mapping the rest onto it as read-only"]', 3, 'On a write to a merged page, the nested table raises a violation and the hypervisor makes a copy for the writer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 5, 4, 'Why is KSM turned off between untrusted tenants?', '["It merges pages too slowly", "From the write time to a merged page one can tell that a neighbor has the same contents", "It breaks nested tables", "It is forbidden by the license"]', 1, 'A write to a merged page is noticeably slower than an ordinary one, which gives a side channel for leaking neighbors'' contents.');
